{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_e9eaf2c93e8d4aad95b359397d23d53e.Models
@using sv_e9eaf2c93e8d4aad95b359397d23d53e.Services
@using sv_e9eaf2c93e8d4aad95b359397d23d53e.Components.Pages.Apply
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h1 class="mb-4">Job Application</h1>

    @if (!_submitted)
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        <div class="card mt-4">
            <div class="card-body">
                @switch (_currentStep)
                {
                    case 1:
                        <PersonalInfoStep FullName="@_fullName"
                                          Email="@_email"
                                          Phone="@_phone"
                                          Address="@_address"
                                          FullNameChanged="v => _fullName = v"
                                          EmailChanged="v => _email = v"
                                          PhoneChanged="v => _phone = v"
                                          AddressChanged="v => _address = v"
                                          ValidationError="@_validationError"
                                          IsValidatingEmail="_isValidatingEmail" />
                        break;
                    case 2:
                        <WorkHistoryStep Entries="_workEntries"
                                         CurrentFlags="_currentJobFlags"
                                         OnAddEntry="AddWorkEntry"
                                         OnRemoveEntry="RemoveWorkEntry"
                                         OnToggleCurrent="ToggleCurrentJob"
                                         ValidationError="@_validationError" />
                        break;
                    case 3:
                        <ReferencesStep References="_references"
                                        OnAddReference="AddReference"
                                        OnRemoveReference="RemoveReference"
                                        ValidationError="@_validationError" />
                        break;
                    case 4:
                        <CoverLetterStep CoverLetter="@_coverLetter"
                                         CoverLetterChanged="v => _coverLetter = v"
                                         MaxLength="2000"
                                         ValidationError="@_validationError" />
                        break;
                    case 5:
                        <ReviewStep FullName="@_fullName"
                                    Email="@_email"
                                    Phone="@_phone"
                                    Address="@_address"
                                    WorkEntries="_workEntries"
                                    CurrentFlags="_currentJobFlags"
                                    References="_references"
                                    CoverLetter="@_coverLetter"
                                    OnEditSection="GoToStep"
                                    IsSubmitting="_isSubmitting"
                                    SubmitError="@_submitError" />
                        break;
                }
            </div>
        </div>

        <div class="d-flex justify-content-between mt-3">
            @if (_currentStep > 1)
            {
                <button class="btn btn-outline-secondary" @onclick="PreviousStep" disabled="@_isSubmitting">
                    ← Back
                </button>
            }
            else
            {
                <div></div>
            }

            @if (_currentStep < 5)
            {
                <button class="btn btn-primary" @onclick="NextStep" disabled="@_isValidatingEmail">
                    @if (_isValidatingEmail)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <text>Validating...</text>
                    }
                    else
                    {
                        <text>Next →</text>
                    }
                </button>
            }
            else
            {
                <button class="btn btn-success" @onclick="SubmitApplication" disabled="@_isSubmitting">
                    @if (_isSubmitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                        <text>Submitting...</text>
                    }
                    else
                    {
                        <text>Submit Application</text>
                    }
                </button>
            }
        </div>
    }
    else
    {
        <div class="card mt-4">
            <div class="card-body text-center py-5">
                <div class="mb-3" style="font-size: 3rem;">✅</div>
                <h2 class="text-success">Application Submitted!</h2>
                <p class="lead mt-3">
                    Your application has been received. Your application ID is:
                </p>
                <h3><span class="badge bg-primary">@_applicationId</span></h3>
                <p class="text-muted mt-3">Please save this ID for your records.</p>
            </div>
        </div>
    }
</div>

@code {
    private int _currentStep = 1;
    private HashSet<int> _completedSteps = new();
    private string? _validationError;

    // Step 1 — Personal Info
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private bool _isValidatingEmail;

    // Step 2 — Work History
    private List<WorkEntryModel> _workEntries = new() { new WorkEntryModel() };
    private List<bool> _currentJobFlags = new() { false };

    // Step 3 — References
    private List<ReferenceModel> _references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 — Cover Letter
    private string _coverLetter = "";

    // Step 5 — Submit
    private bool _isSubmitting;
    private string? _submitError;
    private bool _submitted;
    private int _applicationId;

    private void GoToStep(int step)
    {
        if (step <= _currentStep || _completedSteps.Contains(step))
        {
            _validationError = null;
            _currentStep = step;
        }
    }

    private async Task NextStep()
    {
        _validationError = null;

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 1)
        {
            _isValidatingEmail = true;
            StateHasChanged();

            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isValidatingEmail = false;

            if (!emailValid)
            {
                _validationError = "Please enter a valid email address.";
                return;
            }
        }

        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep()
    {
        _validationError = null;
        if (_currentStep > 1)
            _currentStep--;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName))
                    { _validationError = "Full name is required."; return false; }
                if (string.IsNullOrWhiteSpace(_email))
                    { _validationError = "Email is required."; return false; }
                if (string.IsNullOrWhiteSpace(_phone))
                    { _validationError = "Phone number is required."; return false; }
                if (string.IsNullOrWhiteSpace(_address))
                    { _validationError = "Address is required."; return false; }
                return true;

            case 2:
                foreach (var entry in _workEntries)
                {
                    if (string.IsNullOrWhiteSpace(entry.Company))
                        { _validationError = "Company name is required for all entries."; return false; }
                    if (string.IsNullOrWhiteSpace(entry.Title))
                        { _validationError = "Job title is required for all entries."; return false; }
                    if (entry.StartDate == default)
                        { _validationError = "Start date is required for all entries."; return false; }
                }
                return true;

            case 3:
                if (_references.Count < 2)
                    { _validationError = "At least 2 references are required."; return false; }
                foreach (var r in _references)
                {
                    if (string.IsNullOrWhiteSpace(r.Name))
                        { _validationError = "Name is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Relationship))
                        { _validationError = "Relationship is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Email))
                        { _validationError = "Email is required for all references."; return false; }
                    if (string.IsNullOrWhiteSpace(r.Phone))
                        { _validationError = "Phone is required for all references."; return false; }
                }
                return true;

            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter))
                    { _validationError = "Cover letter is required."; return false; }
                if (_coverLetter.Length > 2000)
                    { _validationError = "Cover letter must be 2000 characters or fewer."; return false; }
                return true;

            default:
                return true;
        }
    }

    private async Task SubmitApplication()
    {
        _submitError = null;
        _isSubmitting = true;

        try
        {
            var workEntries = _workEntries.Select((e, i) => new WorkEntry(
                e.Company, e.Title, e.StartDate,
                _currentJobFlags[i] ? null : e.EndDate,
                e.Description
            )).ToList();

            var refs = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

            var application = new JobApplication(
                new PersonalInfo(_fullName, _email, _phone, _address),
                new WorkHistory(workEntries),
                refs,
                _coverLetter
            );

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }

    private void AddWorkEntry()
    {
        _workEntries.Add(new WorkEntryModel());
        _currentJobFlags.Add(false);
    }

    private void RemoveWorkEntry(int index)
    {
        if (_workEntries.Count > 1)
        {
            _workEntries.RemoveAt(index);
            _currentJobFlags.RemoveAt(index);
        }
    }

    private void ToggleCurrentJob(int index)
    {
        _currentJobFlags[index] = !_currentJobFlags[index];
        if (_currentJobFlags[index])
            _workEntries[index].EndDate = null;
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 1)
            _references.RemoveAt(index);
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
