    @for (int i = 0; i < _steps.Length; i++)
    {
        var stepNum = i + 1;
        var isCompleted = CompletedSteps.Contains(stepNum);
        var isCurrent = stepNum == CurrentStep;
        var isClickable = isCompleted && !isCurrent;

        <div class="text-center flex-fill step-item @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(!isCurrent && !isCompleted ? "dimmed" : "")"
             style="cursor: @(isClickable ? "pointer" : "default")"
             @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(stepNum); }">
            <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center rounded-circle
                        @(isCurrent ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")"
                 style="width: 36px; height: 36px; font-size: 0.85rem;">
                @if (isCompleted && !isCurrent)
                {
                    <text>✓</text>
                }
                else
                {
                    @stepNum
                }
            </div>
            <small class="@(isCurrent ? "fw-bold text-primary" : isCompleted ? "text-success" : "text-muted")"
                   style="font-size: 0.75rem;">
                @_steps[i]
            </small>
        </div>
    }
</div>

