@using static sv_e9eaf2c93e8d4aad95b359397d23d53e.Components.Pages.Apply.WorkEntryModel

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

<h4 class="card-title mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button type="button" class="btn btn-sm btn-outline-danger" @onclick="() => OnRemoveEntry.InvokeAsync(index)">
                        Remove
                    </button>
                }
            </div>

            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Company" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="entry.Title" />
                </div>
            </div>

            <div class="row mb-2">
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" @bind="entry.StartDate" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" @bind="entry.EndDate"
                           disabled="@CurrentFlags[index]" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" checked="@CurrentFlags[index]"
                               @onchange="() => OnToggleCurrent.InvokeAsync(index)" />
                        <label class="form-check-label">Currently working here</label>
                    </div>
                </div>
            </div>

            <div class="mb-0">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="2" @bind="entry.Description"></textarea>
            </div>
        </div>
    </div>
}

<button type="button" class="btn btn-outline-primary" @onclick="OnAddEntry">
    + Add Another Position
</button>

@code {
    [Parameter] public List<Apply.WorkEntryModel> Entries { get; set; } = new();
    [Parameter] public List<bool> CurrentFlags { get; set; } = new();
    [Parameter] public EventCallback OnAddEntry { get; set; }
    [Parameter] public EventCallback<int> OnRemoveEntry { get; set; }
    [Parameter] public EventCallback<int> OnToggleCurrent { get; set; }
    [Parameter] public string? ValidationError { get; set; }
}

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

<h4 class="card-title mb-3">References</h4>
<p class="text-muted">Please provide 2–3 professional references.</p>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var reference = References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (References.Count > 1)
                {
                    <button type="button" class="btn btn-sm btn-outline-danger"
                            @onclick="() => OnRemoveReference.InvokeAsync(index)">
                        Remove
                    </button>
                }
            </div>

            <div class="row mb-2">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="reference.Name" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" @bind="reference.Relationship" />
                </div>
            </div>

            <div class="row mb-0">
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" @bind="reference.Email" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" @bind="reference.Phone" />
                </div>
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-primary" @onclick="OnAddReference">
        + Add Reference
    </button>
}

@code {
    [Parameter] public List<Apply.ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback OnAddReference { get; set; }
    [Parameter] public EventCallback<int> OnRemoveReference { get; set; }
    [Parameter] public string? ValidationError { get; set; }
}

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

<h4 class="card-title mb-3">Cover Letter</h4>

<div class="mb-2">
    <textarea class="form-control" rows="10" @oninput="OnInput" value="@CoverLetter"
              maxlength="@MaxLength"></textarea>
</div>

<div class="d-flex justify-content-end">
    <small class="@(CharCount > MaxLength ? "text-danger fw-bold" : "text-muted")">
        @CharCount / @MaxLength characters
    </small>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter] public int MaxLength { get; set; } = 2000;
    [Parameter] public string? ValidationError { get; set; }

    private int CharCount => CoverLetter?.Length ?? 0;

    private async Task OnInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        await CoverLetterChanged.InvokeAsync(value);
    }
}

